178: .ember-field i:nth-child(1) { left: 8%; animation-delay: 0s; }
179: .ember-field i:nth-child(2) { left: 18%; animation-delay: 2.2s; animation-duration: 11s; }
180: .ember-field i:nth-child(3) { left: 31%; animation-delay: 4s; }
